import {t} from './locales.js';
import {fishPondScene} from './fish-scene.js';
import {fishSnapshot} from './fish-snapshot.js';
/** Presentation-only area; no clock, RNG, grants or persistence. @param {import('./engine.js').State} state */
export function renderFishWorld(state){const host=/** @type {HTMLElement} */(document.querySelector('#world'));host.replaceChildren();const snapshot=fishSnapshot(state),source=new DOMParser().parseFromString(fishPondScene(0,snapshot.ponds[0]?.cohorts||[],{feeding:snapshot.ponds[0]?.feeding,aerator:snapshot.ponds[0]?.aerating,efficient:snapshot.ponds[0]?.efficient}),'image/svg+xml'),svg=/** @type {SVGSVGElement} */(/** @type {unknown} */(document.importNode(source.documentElement,true)));svg.setAttribute('viewBox','0 0 900 540');svg.setAttribute('class','farm-scene fish-scene');svg.dataset.paused=String(state.paused);svg.setAttribute('aria-label',t('fishArea'));svg.setAttribute('data-fish-pond','1');const title=document.createElementNS('http://www.w3.org/2000/svg','title');title.textContent=t(snapshot.preview?'fishPreview':'fishArea');svg.prepend(title);host.append(svg);const copy=document.createElement('p');copy.className='world-caption fish-preview-copy';copy.textContent=(snapshot.preview?t('fishPreview')+' · ':'')+snapshot.count+' '+t('fishCount')+' · '+snapshot.ready+' '+t('fishReady');copy.dataset.fishCount=String(snapshot.count);copy.dataset.fishReady=String(snapshot.ready);host.append(copy);const info=document.createElement('p');info.className='fish-school-note';info.textContent=t('fishSchoolHint');host.append(info);const shortcuts=document.createElement('div');shortcuts.className='fish-shortcuts';shortcuts.setAttribute('aria-label',t('fishChooseStation'));host.querySelectorAll('[data-fish-object]').forEach(object=>{const id=object.getAttribute('data-fish-object')||'',label=t('fishStation_'+id);object.setAttribute('aria-label',label);object.setAttribute('role','button');object.setAttribute('tabindex','0');const select=()=>document.dispatchEvent(new CustomEvent('fishobjectselect',{detail:id}));object.addEventListener('click',select);object.addEventListener('keydown',event=>{if(['Enter',' '].includes(/** @type {KeyboardEvent} */(event).key)){event.preventDefault();select();}});const button=document.createElement('button');button.type='button';button.className='action-button';button.dataset.chooseFish=id;button.textContent=label;button.addEventListener('click',select);shortcuts.append(button);});host.append(shortcuts);svg.setAttribute('role','group');}
